questionvariables.text:
/* Randomize diameter of the cylinder */
d_cyl : rand_with_step(6, 20, 2);

/* Randomize diameter of the sphere (always greater than cylinder) */
d_sph : d_cyl + rand_with_step(10, 40, 2);

/* Calculate radii */
r_sph : d_sph / 2;
r_cyl : d_cyl / 2;

/* The volume of water is 4/3 times the volume of the sphere */
fraction : 4/3;

/* Use pi */
pi_val : 22/7;

/* Volume of the sphere */
V_sphere : (4/3) * pi_val * r_sph^3;

/* Volume of water */
V_water : fraction * V_sphere;

/* Depth of water in the cylinder */
h : V_water / (pi_val * r_cyl^2);

/* Convert to decimal and round */
depth : float(h);
Depth_cylinder : decimalplaces(depth, 2);
V_mistake1 : (3/4) * V_sphere;
h_mistake1 : V_mistake1 / (pi_val * r_cyl^2);
depth_mistake1 : decimalplaces(float(h_mistake1), 2);
